fun OrderRepository.save(order: Order) = transaction {
    OrderLines.deleteWhere { OrderLines.orderId eq order.id }
    OrderLines.batchInsert(order.lines) { l ->
        this[OrderLines.orderId] = order.id
        this[OrderLines.sku] = l.sku
    }
}
